-- Dark Chaos - Ascension mount batch 1 (410 mounts: 156 flying, 254 ground)
-- Mounts that exist only in the Ascension 3.3.5a client (its VanityCollection.dbc mount category),
-- deduplicated against the DarkChaos catalogue by appearance (model + effective textures) and by name.
-- Generated by retroport_tools/dc_mount_ascension_pipeline.py from _asc_mounts/plan.json.
-- dc_mount_definitions.expansion = 100 marks them as Ascension content; DC-Collection's
-- expansion filter keys on the spell band 350000-359999.
-- IDs: spell/item 350000-350409 | creature 3466000-3466409 | display 506500-506909 | vendor slots 1289-1698 (NPC 3461020)

-- 1) creature_model_info
DELETE FROM `creature_model_info` WHERE `DisplayID` BETWEEN 506500 AND 506909;

-- 2) creature_template
DELETE FROM `creature_template` WHERE `entry` BETWEEN 3466000 AND 3466409;

-- 3) creature_template_model
DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 3466000 AND 3466409;

-- 4) item_template (Ascension item name; spellid_2 trigger 6 = learn)
DELETE FROM `item_template` WHERE `entry` BETWEEN 350000 AND 350409;

-- 5) npc_vendor (Skeletal Stablemaster; dc_paged_collection_vendor pages the roster)
DELETE FROM `npc_vendor` WHERE `entry`=3461020 AND `item` BETWEEN 350000 AND 350409;
DELETE FROM `npc_vendor` WHERE `entry`=3461020 AND `slot` BETWEEN 1289 AND 1698;

-- 6) conditions cleanup
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId`=23 AND `SourceGroup`=3461020 AND `SourceEntry` BETWEEN 350000 AND 350409 AND `ConditionTypeOrReference`=25;

-- 7) dc_mount_definitions (fly = type 3 / 310, ground = type 0 / 100; expansion 100 = Ascension)
DELETE FROM `dc_mount_definitions` WHERE `spell_id` BETWEEN 350000 AND 350409;
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`mount_type`=VALUES(`mount_type`),`source`=VALUES(`source`),`faction`=VALUES(`faction`),`rarity`=VALUES(`rarity`),`speed`=VALUES(`speed`),`display_id`=VALUES(`display_id`),`expansion`=VALUES(`expansion`);

-- 8) dc_collection_definitions (collection_type 1 = MOUNT)
DELETE FROM `dc_collection_definitions` WHERE `collection_type`=1 AND `entry_id` BETWEEN 350000 AND 350409;
